void GinJavaBridgeRemoteObjectAsyncWaiter::GetMethods(
    std::vector<std::string>* out_method_names) {
  base::RunLoop loop;
  proxy_->GetMethods(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<std::string>* out_method_names
,
             const std::vector<std::string>& method_names) {*out_method_names = std::move(method_names);
            loop->Quit();
          },
          &loop,
          out_method_names));
  loop.Run();
}

